      },
      [showTooltip],
    );

    const handlePointerDown = (event: ReactPointerEvent<SVGSVGElement>) => {
      if (!draggable) return;
      if (event.isPrimary === false || event.button !== 0) return;
      if (
        event.target instanceof Element &&
        event.target.closest('[data-globe-marker-interactive="true"]')
      ) {
        return;
      }
