      [],
    );

    return (
      <div
        ref={ref}
        className={cn("relative w-full overflow-hidden", className)}
        style={height === undefined ? { aspectRatio: "1" } : { height }}
        onFocusCapture={() => {
          isFocusedRef.current = true;
        }}
        onBlurCapture={(event) => {
          if (!event.currentTarget.contains(event.relatedTarget)) {
