        <svg
          ref={svgRef}
          role="group"
          aria-label={ariaLabel}
          aria-describedby={draggable ? instructionsId : undefined}
          tabIndex={draggable ? 0 : undefined}
          viewBox={`0 0 ${GLOBE_VIEWBOX_SIZE} ${GLOBE_VIEWBOX_SIZE}`}
