  return (
    <Chart
      echarts={ec}
      ref={mergedRef}
      options={options}
      className={className}
      isDarkMode={isDarkMode}
      height={height}
      aspectRatio={resolvedAspect}
      onEvents={onEvents}
    />
  );
}

